  root.MADO_SPOT_PAGE_DATA = {"id":"fujikawa-bridge","lang":"en","name":"Fujikawa Bridge and the Water Pipe Bridge","area":"Shin-Fuji → Shizuoka","hook":"River and Fuji in one frame.","headingChunks":["Mt. Fuji beyond the white arches","of the Fuji River"],"heading":"Mt. Fuji beyond the white arches of the Fuji River","sectionHeading":"What the water pipe bridge is, and why it is a row of arches","story":"The Fujikawa Bridge that the Shinkansen crosses is not the white one. Running parallel just upstream is the Fujikawa water pipe bridge: about 1,040 metres long, formed of ten white arches. The arches are structure, not decoration — this is a Langer design in which a 2,200-millimetre steel pipe is itself stiffened by the arch above it. The water main is not carried by the bridge; the water main is the bridge. When it was built in the late 1960s it was the largest of its type in Japan and among the longest water pipe bridges in the world; Fuji City's public magazine put it on its cover in 1970 as the world's greatest water pipe bridge. What flows through it is industrial water, not drinking water, and it is bound for the paper mills downstream.","minutes":47,"side":"E","sideLabel":"Seat E · right side toward Kyoto","spotting":"easy","facts":{"labels":["Section","Seat side","Timing","Photos"],"timing":"About 47 minutes after leaving Tokyo on a Nozomi train","photoUnit":"photos"},"photos":[{"src":"images/20220205_fujikawa_bridge_michikusa.jpg","thumb":"images/thumbs/20220205_fujikawa_bridge_michikusa.webp","alt":"Fujikawa Bridge and the Water Pipe Bridge from the Shinkansen window","note":"5 February 2022: a snow-capped Mt. Fuji above the ten white arches.","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":""},{"src":"images/20260903_fujikawa_cloudy_michikusa.jpg","thumb":"images/thumbs/20260903_fujikawa_cloudy_michikusa.webp","alt":"The Fuji River from a Shinkansen window under cloud","note":"On a cloudy day, the river's width and white arches stand out","credit":"michikusa","sourceUrl":"","date":"2026-09-03","heading":"","intro":"","caption":""}],"hero":{"src":"images/20220205_fujikawa_bridge_michikusa.jpg","thumb":"images/thumbs/20220205_fujikawa_bridge_michikusa.webp","alt":"Fujikawa Bridge and the Water Pipe Bridge from the Shinkansen window","note":"5 February 2022: a snow-capped Mt. Fuji above the ten white arches.","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":""},"gallery":[{"src":"images/20220205_fujikawa_bridge_michikusa.jpg","thumb":"images/thumbs/20220205_fujikawa_bridge_michikusa.webp","alt":"Fujikawa Bridge and the Water Pipe Bridge from the Shinkansen window","note":"5 February 2022: a snow-capped Mt. Fuji above the ten white arches.","credit":"michikusa","sourceUrl":"","date":"","heading":"","intro":"","caption":""},{"src":"images/20260903_fujikawa_cloudy_michikusa.jpg","thumb":"images/thumbs/20260903_fujikawa_cloudy_michikusa.webp","alt":"The Fuji River from a Shinkansen window under cloud","note":"On a cloudy day, the river's width and white arches stand out","credit":"michikusa","sourceUrl":"","date":"2026-09-03","heading":"","intro":"","caption":""}],"photoHeading":"Fujikawa Bridge and the Water Pipe Bridge in photos","photoHeadingCustom":false,"inline":[],"photoTip":null,"bodyLinks":[{"label":"Surugawan Hyakkei: the Tokaido Shinkansen Fujikawa Bridge (Japanese only)","href":"https://www.surugawan.net/guide/556.html"},{"label":"Doboku Watching: the Fujikawa water pipe bridge (Japanese only)","href":"https://www.doboku-watching.com/index.php?kijiId=543"}],"routeNote":"If you are traveling from Tokyo toward Shin-Osaka, start watching the right-hand window (Seat E) as you approach Shin-Fuji → Shizuoka. If you are traveling toward Tokyo, the order is reversed and the same Seat E is on your left.","fujiGuide":null,"explainer":{"heading":"How to spend the dozen seconds","paragraphs":["Once you leave Shin-Fuji, stay at the Seat E window. As the train reaches the bridge the view opens onto a broad gravel riverbed and the water, with the row of white arches upstream. Mt. Fuji stands ahead and slightly right, beyond the arches.","A tunnel begins the moment the crossing ends. There is no time to notice it and then go looking — the only trick is to be ready as you pull out of Shin-Fuji.","Winter and early spring are the best pairing: a snow-capped Fuji above white arches. In summer the mountain tends to dissolve into the sky, and it is more realistic to enjoy the arches and the width of the riverbed instead.","The Seat A side looks downstream toward Suruga Bay. There is no Mt. Fuji, but the riverbed widens toward the mouth and the sea is sometimes visible in the distance."],"figure":null},"referenceImage":null,"sharedGuide":[],"guideNotice":null,"map":{"hasCoordinates":true,"lat":35.131,"lng":138.5985,"name":"Fujikawa water pipe bridge","externalUrl":"https://www.google.com/maps/search/?api=1&query=35.131%2C138.5985","embedUrl":"https://www.google.com/maps/embed/v1/place?key=AIzaSyDE3UdN_9m9cK5sLTlfuc7KElsfceYNwrs&q=35.131%2C138.5985&center=35.131%2C138.5985&zoom=14&maptype=satellite&language=en","viewpointUrl":"https://www.google.com/maps/embed/v1/place?key=AIzaSyDE3UdN_9m9cK5sLTlfuc7KElsfceYNwrs&q=35.1265%2C138.5945&center=35.131%2C138.5985&zoom=14&maptype=satellite&language=en","viewpoint":{"lat":35.1265,"lng":138.5945}},"guide":{"title":"How to catch Fujikawa Bridge and the Water Pipe Bridge","intro":"As you approach Shin-Fuji → Shizuoka, start watching from Seat E · right side toward Kyoto. Use Audio Guide while riding, or the map on this page before you board.","duration":"The view lasts roughly 10 to 20 seconds, though buildings and terrain may interrupt it. Start watching a little early.","timingLead":"Know your train? Select it to see this view's estimated time on the actual timetable.","cta":"Select my train and check the time","href":"../../en/start.html#journey","highlight":"Be at the Seat E window as you leave Shin-Fuji. The moment the train reaches the bridge the riverbed opens up and the white arches line up upstream, with Mt. Fuji beyond them. A tunnel follows straight after the crossing, so starting to look once you are on the bridge is already too late."},"references":[{"label":"Surugawan Hyakkei: the Tokaido Shinkansen Fujikawa Bridge (Japanese only)","href":"https://www.surugawan.net/guide/556.html"},{"label":"Doboku Watching: the Fujikawa water pipe bridge (Japanese only)","href":"https://www.doboku-watching.com/index.php?kijiId=543"}],"related":[{"id":"fuji","href":"fuji.html","thumb":"images/thumbs/20210218_fuji_rumireport.webp","label":"Related","name":"Mt. Fuji","hook":"Japan's famous three minutes."},{"id":"fuji-paper-mills","href":"fuji-paper-mills.html","thumb":"images/thumbs/20241129_fuji_paper_mills_OliverinJapan.webp","label":"Related","name":"Fuji's Paper Mills","hook":"Fuji's foothills make paper."},{"id":"shimizu-port-chikyu","href":"shimizu-port-chikyu.html","thumb":"images/thumbs/20240119_shimizu_port_chikyu_senba16530315.webp","label":"Related","name":"Shimizu Port and CHIKYU","hook":"A white drilling tower at port."}],"media":null,"showcase":false,"stamp":{"src":"images/stamps/stamp_fujikawa-bridge.svg","label":"Window stamp","alt":"Fujikawa Bridge and the Water Pipe Bridge window stamp"}};
